  3912          start = gf_bs_get_position(bs);
  3913          gf_bs_seek(bs, start + 8);
  3914          v = gf_bs_read_u16(bs);
  3915          if (v)
  3916                  ptr->qtff_mode = GF_ISOM_AUDIO_QTFF_ON_NOEXT;
  3917
  3918          //try to disambiguate QTFF v1 and MP4 v1 audio sample entries ...
  3919          if (v==1) {
  3920                  //go to end of ISOM audio sample entry, skip 4 byte (box size field), read 4 bytes (box type) and check if this looks like a box
  3921                  gf_bs_seek(bs, start + 8 + 20  + 4);
  3922                  a = gf_bs_read_u8(bs);
  3923                  b = gf_bs_read_u8(bs);
  3924                  c = gf_bs_read_u8(bs);
  3925                  d = gf_bs_read_u8(bs);
  3926                  nb_alnum = 0;
  3927                  if (isalnum(a)) nb_alnum++;
  3928                  if (isalnum(b)) nb_alnum++;
  3929                  if (isalnum(c)) nb_alnum++;
  3930                  if (isalnum(d)) nb_alnum++;
  3931                  if (nb_alnum>2) ptr->qtff_mode = GF_ISOM_AUDIO_QTFF_NONE;
  3932          }
  3933
  3934          gf_bs_seek(bs, start);
  3935          e = gf_isom_audio_sample_entry_read((GF_AudioSampleEntryBox*)s, bs);
  3936          if (e) return e;
  3937          pos = gf_bs_get_position(bs);
  3938          size = (u32) s->size;
  3939
  3940          //when cookie is set on bs, always convert qtff-style mp4a to isobmff-style
  3941          //since the conversion is done in addBox and we don't have the bitstream there (arg...), flag the box
  3942          if (gf_bs_get_cookie(bs) & GF_ISOM_BS_COOKIE_QT_CONV) {
  3943                  ptr->qtff_mode |= GF_ISOM_AUDIO_QTFF_CONVERT_FLAG;
  3944          }
